from __future__ import annotations

import abc
import pathlib
from abc import ABCMeta
from contextlib import contextmanager
from typing import Generator, Optional

import attr
from lxml import etree

from taf.ul.ue.sim.env_setup.devices.device import Device


@attr.s
class Simulator(Device, metaclass=ABCMeta):
    def configure(self, *args: Optional[tuple], **kwargs: Optional[dict]) -> None:
        try:
            return self._configure(*args, **kwargs)
        except Exception as err:
            self.logger.debug(err, exc_info=True)
            if kwargs.get("warning_lookup"):
                raise
            self.logger_recovery.info(err)
            self._recovery_for_simulator_configuration()
            return self._configure(*args, **kwargs)

    def _recovery_for_simulator_configuration(self) -> None:
        self.reset()
        with self._get_remote_host_ssh() as ssh_connection:
            self._wait_until_host_is_available(ssh_connection, timeout=300)
            self._wait_until_constant_pingable(ssh_connection)
            self._wait_for_host_ssh(ssh_connection, timeout=30)
        self.logger.debug(f"Recovery for {self.name} succeeded")

    def get_rmods_count(self) -> int:
        alias = f"get_rmods_count_id_{self.idx}_host_{self.remote_host}"
        if self.pdu.get_pdu_status(alias, self.logger) == "off":
            return 0
        wts_config_path = pathlib.Path(self.output_directory_path, "iphy.xml")
        with self._get_remote_host_ssh() as ssh_connection:
            with self._get_device_ssh(ssh_connection) as device_ssh:
                device_ssh.files.get(
                    "readlink -f /ffs/run/simmode/iphy.xml",
                    wts_config_path.as_posix(),
                    timeout=30,
                )
        rmod_count = self._count_rmods_in_xml(wts_config_path.as_posix())
        return rmod_count

    @abc.abstractmethod
    def _configure(self, *args, **kwargs) -> None: ...

    def _count_rmods_in_xml(self, xml_file: str) -> int:
        """
        :param xml_file:
        :return:
        """
        with self.open_rmods_xml(xml_file) as xml:
            rrh_count = len(xml.findall(".//RRH"))
            re_count = len(xml.findall(".//RE"))
        rmod_count = rrh_count + re_count
        return rmod_count

    @staticmethod
    @contextmanager
    def open_rmods_xml(path: str) -> Generator[etree._ElementTree, None, None]:
        """

        :param path:
        :return:
        """
        try:
            xml = etree.parse(path)
        except etree.XMLSyntaxError:
            root = etree.XML("""<?xml version="1.0"?><root></root>""")
            xml = etree.ElementTree(root)
        yield xml
        xml.write(path)
